//! The w17 vocabulary as Rust types: every package under `w17` (ErrorDetail,
//! Paging, InvalidateEvent, the options, `w17.common.distx`,
//! `w17.common.files`), generated by this crate's build from
//! `src/sdk_descriptors.binpb`.
//!
//! An author's crate maps `.w17` onto this module (`w17-business-build`), so
//! a vocabulary message that crosses into the SDK is one type, not two.

#![allow(missing_docs, clippy::all, clippy::pedantic)]

include!(concat!(env!("OUT_DIR"), "/w17_sdk_protos.rs"));

/// `google.protobuf` (the well-known types) and `google.rpc` (the error
/// details), re-exported so an author's crate needs neither `prost-types` nor
/// `tonic-types`.
pub mod google {
    pub mod protobuf {
        pub use prost_types::*;
    }
    pub mod rpc {
        pub use tonic_types::pb::*;
    }
}
